<?phpnamespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;class ListingModelo extends Model{    use HasFactory;        protected $table = 'listing_modelo';    protected $fillable = ['listing_id', 'modelo_id', 'canal'];    public function modelo()    {        return $this->belongsTo(Modelo::class, 'modelo_id');    }}